/**
 * Load embedded data into the application
 */
function loadEmbeddedData() {
    console.log('Loading embedded service area data...');

    // Clear any existing data
    state.crematoryData = [];
    state.serviceAreaZips.clear();
    state.crematoryZips.clear();
    state.zipToCityCounty.clear();
    state.crematoryMarkers.forEach(m => state.map.removeLayer(m));
    state.crematoryMarkers = [];

    // Load crematories
    CREMATORY_LOCATIONS.forEach(crem => {
        const crematory = {
            name: crem.name,
            address: crem.address,
            lat: crem.lat,
            lng: crem.lng,
            assignedZips: []
        };
        state.crematoryData.push(crematory);
        addCrematoryMarker(crematory);
    });

    // Load FPG/Monarch partner crematories (red markers)
    if (typeof FPG_CREMATORY_LOCATIONS !== 'undefined') {
        FPG_CREMATORY_LOCATIONS.forEach(crem => {
            addFPGCrematoryMarker(crem);
        });
        console.log(`- ${FPG_CREMATORY_LOCATIONS.length} FPG partner crematories`);
    }

    // Load service areas by county
    Object.entries(SERVICE_AREA_DATA).forEach(([county, zips]) => {
        Object.entries(zips).forEach(([zip, crematoryNames]) => {
            // Add to service area
            state.serviceAreaZips.add(zip);

            // Store county info
            state.zipToCityCounty.set(zip, { city: '', county: county });

            // Get or create zip data
            let zipData = state.zipCodeData.get(zip);
            if (!zipData) {
                zipData = {
                    serviceArea: true,
                    crematories: [],
                    hasCrematory: false
                };
            }
            zipData.serviceArea = true;
            zipData.crematories = [];

            // Link crematories
            crematoryNames.forEach(cremName => {
                const crem = state.crematoryData.find(c => c.name === cremName);
                if (crem) {
                    if (!crem.assignedZips.includes(zip)) {
                        crem.assignedZips.push(zip);
                    }
                    zipData.crematories.push({
                        name: crem.name,
                        distance: null,
                        driveTime: null
                    });
                }
            });

            state.zipCodeData.set(zip, zipData);
        });
    });

    // Mark crematory locations
    CREMATORY_ZIP_CODES.forEach(zip => {
        state.crematoryZips.add(zip);
        const zipData = state.zipCodeData.get(zip);
        if (zipData) {
            zipData.hasCrematory = true;
        }
    });

    // Populate city/county data for all zips
    populateZipCityCountyData();

    // Calculate distances
    calculateDistances();

    // Calculate nearby zips (within 42 miles of any crematory)
    calculateNearbyZips();

    // Refresh UI
    refreshMapStyles();
    updateStatisticsPanel();
    updateCrematoriesPanel();

    state.isDataLoaded = true;
    document.getElementById('exportBtn').disabled = false;

    console.log('Embedded data loaded successfully!');
    console.log(`- ${state.crematoryData.length} crematories`);
    console.log(`- ${state.serviceAreaZips.size} service area zip codes`);
    console.log(`- ${state.nearbyZips.size} nearby zip codes (within ${CONFIG.nearbyDistanceThreshold} miles)`);
}

